node << 'EOF'
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const FILE = 'file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/rocket-launch/2026-08-13-cursor-agent-cursor-grok-4-6-high/index.html';
const OUT = '/tmp/rocket-launch-check';
const PORT = 9333;

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function getWsUrl() {
  const res = await fetch('http://127.0.0.1:' + PORT + '/json/list');
  const list = await res.json();
  const page = list.find(p => p.type === 'page') || list[0];
  return page.webSocketDebuggerUrl;
}

function cdp(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    let id = 0;
    const pending = new Map();
    ws.onopen = () => resolve({
      send(method, params = {}) {
        const n = ++id;
        ws.send(JSON.stringify({ id: n, method, params }));
        return new Promise((res, rej) => pending.set(n, { res, rej }));
      },
      close() { ws.close(); }
    });
    ws.onerror = reject;
    ws.onmessage = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && pending.has(msg.id)) {
        const { res, rej } = pending.get(msg.id);
        pending.delete(msg.id);
        if (msg.error) rej(new Error(JSON.stringify(msg.error)));
        else res(msg.result);
      }
    };
  });
}

(async () => {
  const chrome = spawn(CHROME, [
    '--headless=new',
    '--disable-gpu',
    '--hide-scrollbars',
    '--remote-debugging-port=' + PORT,
    '--window-size=1400,900',
    FILE
  ], { stdio: 'ignore' });

  try {
    for (let i = 0; i < 20; i++) {
      try { await getWsUrl(); break; } catch { await sleep(150); }
    }
    const wsUrl = await getWsUrl();
    const client = await cdp(wsUrl);
    await client.send('Page.enable');
    await client.send('Runtime.enable');

    const times = [400, 1800, 3500, 5500, 9000, 14000];
    for (const ms of times) {
      await sleep(ms === times[0] ? ms : ms - times[times.indexOf(ms) - 1]);
      const shot = await client.send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync(path.join(OUT, 'live' + ms + '.png'), Buffer.from(shot.data, 'base64'));
      console.log('saved live' + ms);
    }
    client.close();
  } finally {
    chrome.kill('SIGKILL');
  }
})().catch(e => { console.error(e); process.exit(1); });
